    /**
     * Returns the number of rows matching criteria, joining all related tables
     *
     * @param      Criteria $criteria
     * @param      boolean $distinct Whether to select only distinct columns; deprecated: use Criteria->setDistinct() instead.
     * @param      PropelPDO $con
     * @param      String    $join_behavior the type of joins to use, defaults to Criteria::LEFT_JOIN
     * @return int Number of matching rows.
     */
    public static function doCountJoinAll(Criteria $criteria, $distinct = false, PropelPDO $con = null, $join_behavior = Criteria::LEFT_JOIN)
    {
        // we're going to modify criteria, so copy it first
        $criteria = clone $criteria;

        // We need to set the primary table name, since in the case that there are no WHERE columns
        // it will be impossible for the BasePeer::createSelectSql() method to determine which
        // tables go into the FROM clause.
        $criteria->setPrimaryTableName(ServicioPeer::TABLE_NAME);

        if ($distinct && !in_array(Criteria::DISTINCT, $criteria->getSelectModifiers())) {
            $criteria->setDistinct();
        }

        if (!$criteria->hasSelectClause()) {
            ServicioPeer::addSelectColumns($criteria);
        }

        $criteria->clearOrderByColumns(); // ORDER BY won't ever affect the count

        // Set the correct dbName
        $criteria->setDbName(ServicioPeer::DATABASE_NAME);

        if ($con === null) {
            $con = Propel::getConnection(ServicioPeer::DATABASE_NAME, Propel::CONNECTION_READ);
        }

        $criteria->addJoin(ServicioPeer::USUARIO_ID, UsuarioPeer::USUARIO_ID, $join_behavior);

        $criteria->addJoin(ServicioPeer::EMPRESA_MENSAJERIA_ID, EmpresaMensajeriaPeer::EMPRESA_MENSAJERIA_ID, $join_behavior);

        $criteria->addJoin(ServicioPeer::PERIODO_ID, PeriodoPeer::PERIODO_ID, $join_behavior);

        $criteria->addJoin(ServicioPeer::PRIORIDADSOLICITUDSERVICIO_ID, PrioridadSolicitudServicioPeer::PRIORIDADSOLICITUDSERVICIO_ID, $join_behavior);

        $criteria->addJoin(ServicioPeer::DIRECTORIOEXTERNO_ID, DirectorioExternoPeer::DIRECTORIOEXTERNO_ID, $join_behavior);

        $criteria->addJoin(ServicioPeer::TIPOSERVICIO_ID, TipoServicioPeer::TIPOSERVICIO_ID, $join_behavior);

        $criteria->addJoin(ServicioPeer::REGIONAL_ID, RegionalPeer::REGIONAL_ID, $join_behavior);

        $criteria->addJoin(ServicioPeer::SERVICIOESTADO_ID, ServicioEstadoPeer::SERVICIOESTADO_ID, $join_behavior);

        $criteria->addJoin(ServicioPeer::SERVICIOTIPODEVOLUCION_ID, ServicioTipoDevolucionPeer::SERVICIOTIPODEVOLUCION_ID, $join_behavior);

        $criteria->addJoin(ServicioPeer::MODULO_ID, ModuloPeer::MODULO_ID, $join_behavior);

        $criteria->addJoin(ServicioPeer::MARCONORMATIVO_ID, MarcoNormativoPeer::MARCONORMATIVO_ID, $join_behavior);

        $criteria->addJoin(ServicioPeer::PROCESODOCORIGEN_ID, ProcesodocOrigenPeer::PROCESODOCORIGEN_ID, $join_behavior);

        // symfony_behaviors behavior
        foreach (sfMixer::getCallables(self::getMixerPreSelectHook(__FUNCTION__)) as $sf_hook)
        {
          call_user_func($sf_hook, 'BaseServicioPeer', $criteria, $con);
        }

        $stmt = BasePeer::doCount($criteria, $con);

        if ($row = $stmt->fetch(PDO::FETCH_NUM)) {
            $count = (int) $row[0];
        } else {
            $count = 0; // no rows returned; we infer that means 0 matches.
        }
        $stmt->closeCursor();

        return $count;
    }

